local f=workspace.InstallationMenu local b=game.ServerStorage:FindFirstChild("AnciensScripts") or Instance.new("Folder",game.ServerStorage) b.Name="AnciensScripts" for n,p in {InventoryUI=game.StarterGui,GrassServer=game.ServerScriptService,GrassClient=game.StarterPlayer.StarterPlayerScripts} do local v=p:FindFirstChild(n) while v do v.Enabled=false v.Name=n.."_ANCIEN" v.Parent=b v=p:FindFirstChild(n) end f[n].Parent=p end f:Destroy() print("Installation OK !")
